import * as Store from "./Store.js";
// Re-reading one issue from GitHub into the projection (decision 0012 §2): a webhook only names its subject, and a write
// reads back what it made, so both come here. GitHub is the truth, so the row is what GitHub answers now, under the
// newer-than guard; an issue GitHub answers 404 or 410 for is tombstoned with its comments. Reading (GitHub) and writing
// (Postgres) are separate, so a write settles its row and its projection in one transaction without holding it open
// across a call to GitHub.
